56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	};
63	
64	const quotePremium = (items: QuoteItem[]): number => {
65	  const basePremium = items.reduce(
66	    (sum, item) => sum + BASE_PREMIUMS[item.type],
67	    0,
68	  );
69	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
70	  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
71	};
72	
73	export const runScenario = (scenario: Scenario): ScenarioOutput => {
74	  const quoteStep = scenario.steps[0] as QuoteStep;
75	  return { results: [{ premium: quotePremium(quoteStep.items) }] };
76	};
